pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testFuzz_property(address from, address to, uint256 v) public {
        vm.assume(from != address(0));
        vm.assume(to != address(0));
        bytes4 sel = bytes4(keccak256("transferFrom(address,address,uint256)"));
        bytes memory expected = abi.encodeWithSelector(sel, from, to, v);
        Recorder r = new Recorder();
        address[] memory tos = new address[](1);
        tos[0] = to;
        c.transfer(from, address(r), tos, v);
        assertTrue(keccak256(r.lastData()) == keccak256(expected));
    }
}

contract Recorder {
    bytes public lastData;
    fallback() external payable {
        lastData = msg.data;
    }
}
